package task

import "testing"

func TestLRUEviction(t *testing.T) {
	c := NewLRU(2)
	c.Put("a", "1")
	c.Put("b", "2")
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Fatalf("Get(a) = %q, %v; want 1, true", v, ok)
	}
	// a только что использовался — вытеснится b.
	c.Put("c", "3")
	if _, ok := c.Get("b"); ok {
		t.Error("b должен быть вытеснен")
	}
	if v, ok := c.Get("a"); !ok || v != "1" {
		t.Errorf("Get(a) после вытеснения = %q, %v", v, ok)
	}
	if v, ok := c.Get("c"); !ok || v != "3" {
		t.Errorf("Get(c) = %q, %v", v, ok)
	}
}

func TestLRUUpdate(t *testing.T) {
	c := NewLRU(1)
	c.Put("a", "1")
	c.Put("a", "2")
	if v, ok := c.Get("a"); !ok || v != "2" {
		t.Errorf("обновление не сработало: %q, %v", v, ok)
	}
	if _, ok := c.Get("nope"); ok {
		t.Error("несуществующий ключ вернул ok=true")
	}
}

