package task

import "testing"

func TestParallelSum(t *testing.T) {
	if got := ParallelSum(nil, 4); got != 0 {
		t.Errorf("пустой срез: %d", got)
	}
	nums := make([]int, 10_000)
	want := 0
	for i := range nums {
		nums[i] = i
		want += i
	}
	for _, w := range []int{1, 2, 4, 8, 100} {
		if got := ParallelSum(nums, w); got != want {
			t.Errorf("workers=%d: got %d, want %d", w, got, want)
		}
	}
	if got := ParallelSum([]int{-1, 1, -2, 2}, 2); got != 0 {
		t.Errorf("знаки: %d", got)
	}
}

